begin;

insert into public.blog_posts (
  slug,
  title,
  excerpt,
  content,
  paragraph_1,
  paragraph_2,
  paragraph_3,
  paragraph_4,
  category,
  author_name,
  image_urls,
  image_alt_texts,
  image_url_1,
  image_url_2,
  source_links,
  relevant_link,
  link_title,
  published,
  published_at
) values (
  '2025-match-statistics-lessons-for-2027-applicants',
  'What the 2025 Match Statistics Mean for 2027 Applicants',
  'The 2025 Match was record-setting, but its most useful lesson is not that any specialty is “easy.” Applicant type, specialty growth, fill patterns, and a well-researched program list must be interpreted together.',
  concat_ws(
    E'\n\n',
    $article$The 2025 Main Residency Match was the largest at the time: 52,498 people registered, 47,208 became active applicants by certifying a rank order list, and 37,667 matched to a PGY-1 position. Programs offered 43,237 positions overall, including a record 40,041 PGY-1 positions. The headline match rates, however, were not evenly distributed. U.S. MD seniors matched to PGY-1 positions at 93.5%, U.S. DO seniors at a record 92.6%, U.S.-citizen international medical graduates (IMGs) at 67.8%, and non-U.S.-citizen IMGs at 58.0%. The DO rate had risen from 89.1% in 2021, while the number of matched DO seniors grew from 6,327 to 7,773. That narrowing top-line gap is encouraging, but an overall rate does not erase specialty-specific differences, and it cannot predict one applicant’s result.$article$,
    $article$The specialty tables add the context applicants need. Family Medicine offered 5,357 PGY-1 positions but filled 4,552 in the matching algorithm, leaving 805 unfilled—a fill rate of 85.0%. Categorical Pediatrics left 147 of 3,135 positions unfilled, while categorical Internal Medicine left 357 of 10,941 unfilled and still filled 96.7%. Those openings did not make every program interchangeable or guarantee a later SOAP offer. At the same time, capacity expanded: from 2021 to 2025, categorical Internal Medicine grew from 9,024 to 10,941 positions, and Neurology grew from 715 to 932, a 30.3% increase. Emergency Medicine also rebounded from an 81.8% fill rate in 2023 to 97.9% in 2025. Growth and unfilled counts show where the system is changing; they do not measure how competitive a particular program will be for a particular applicant.$article$,
    $article$For IMGs, the 2025 data support a targeted strategy rather than either false reassurance or defeatism. There were 11,465 active non-U.S.-citizen IMG applicants, up 14.4% from 2024; 6,653 matched to PGY-1 positions, while another 1,782 registered but submitted no rank list. Non-U.S. IMGs filled 3,573 categorical Internal Medicine positions, 801 Family Medicine positions, 590 categorical Pediatrics positions, and 223 Neurology positions. These totals show meaningful pathways, especially in broad-entry fields, but they are not program-level acceptance rates. For the next Match, build a list from current evidence: confirm visa sponsorship, graduation-year and attempt filters, US clinical experience expectations, application service, and each program’s actual resident profile. Apply broadly enough for your risk level, but do not substitute a national specialty total for program-specific fit.$article$,
    $article$The practical 2027 plan is to use the 2025 results as a baseline, then verify every current rule before acting. Strengthen the parts of the application that travel across specialties—accurate experiences, strong specialty-relevant letters, a clear personal narrative, interview readiness, and an honest account of your clinical and scholarly work. Research programs before applications become available to them on September 23, 2026, register for the NRMP beginning September 15, and remember that applying through ERAS or ResidencyCAS is separate from registering in the NRMP R3 system. Ranking opens February 1, 2027, and rank order lists must be certified by 9 p.m. ET on March 3. Use the numbers to calibrate your list and prepare contingencies, not to chase a supposedly easy specialty. Rank programs in your true order of preference, keep a SOAP plan ready, and revisit current NRMP data and each program’s requirements before every major decision.$article$
  ),
  $article$The 2025 Main Residency Match was the largest at the time: 52,498 people registered, 47,208 became active applicants by certifying a rank order list, and 37,667 matched to a PGY-1 position. Programs offered 43,237 positions overall, including a record 40,041 PGY-1 positions. The headline match rates, however, were not evenly distributed. U.S. MD seniors matched to PGY-1 positions at 93.5%, U.S. DO seniors at a record 92.6%, U.S.-citizen international medical graduates (IMGs) at 67.8%, and non-U.S.-citizen IMGs at 58.0%. The DO rate had risen from 89.1% in 2021, while the number of matched DO seniors grew from 6,327 to 7,773. That narrowing top-line gap is encouraging, but an overall rate does not erase specialty-specific differences, and it cannot predict one applicant’s result.$article$,
  $article$The specialty tables add the context applicants need. Family Medicine offered 5,357 PGY-1 positions but filled 4,552 in the matching algorithm, leaving 805 unfilled—a fill rate of 85.0%. Categorical Pediatrics left 147 of 3,135 positions unfilled, while categorical Internal Medicine left 357 of 10,941 unfilled and still filled 96.7%. Those openings did not make every program interchangeable or guarantee a later SOAP offer. At the same time, capacity expanded: from 2021 to 2025, categorical Internal Medicine grew from 9,024 to 10,941 positions, and Neurology grew from 715 to 932, a 30.3% increase. Emergency Medicine also rebounded from an 81.8% fill rate in 2023 to 97.9% in 2025. Growth and unfilled counts show where the system is changing; they do not measure how competitive a particular program will be for a particular applicant.$article$,
  $article$For IMGs, the 2025 data support a targeted strategy rather than either false reassurance or defeatism. There were 11,465 active non-U.S.-citizen IMG applicants, up 14.4% from 2024; 6,653 matched to PGY-1 positions, while another 1,782 registered but submitted no rank list. Non-U.S. IMGs filled 3,573 categorical Internal Medicine positions, 801 Family Medicine positions, 590 categorical Pediatrics positions, and 223 Neurology positions. These totals show meaningful pathways, especially in broad-entry fields, but they are not program-level acceptance rates. For the next Match, build a list from current evidence: confirm visa sponsorship, graduation-year and attempt filters, US clinical experience expectations, application service, and each program’s actual resident profile. Apply broadly enough for your risk level, but do not substitute a national specialty total for program-specific fit.$article$,
  $article$The practical 2027 plan is to use the 2025 results as a baseline, then verify every current rule before acting. Strengthen the parts of the application that travel across specialties—accurate experiences, strong specialty-relevant letters, a clear personal narrative, interview readiness, and an honest account of your clinical and scholarly work. Research programs before applications become available to them on September 23, 2026, register for the NRMP beginning September 15, and remember that applying through ERAS or ResidencyCAS is separate from registering in the NRMP R3 system. Ranking opens February 1, 2027, and rank order lists must be certified by 9 p.m. ET on March 3. Use the numbers to calibrate your list and prepare contingencies, not to chase a supposedly easy specialty. Rank programs in your true order of preference, keep a SOAP plan ready, and revisit current NRMP data and each program’s requirements before every major decision.$article$,
  'Residency Interviews',
  'Magna-Q Editorial Team',
  array[
    'https://images.unsplash.com/photo-1532094349884-543bc11b234d?auto=format&fit=crop&w=1400&q=80',
    'https://images.unsplash.com/photo-1588196749597-9ff075ee6b5b?auto=format&fit=crop&w=1400&q=80'
  ],
  array[
    'Medical team reviewing research data together',
    'Residency applicant preparing at a laptop'
  ],
  'https://images.unsplash.com/photo-1532094349884-543bc11b234d?auto=format&fit=crop&w=1400&q=80',
  'https://images.unsplash.com/photo-1588196749597-9ff075ee6b5b?auto=format&fit=crop&w=1400&q=80',
  '[
    {"title":"NRMP: Advance Data Tables for the 2025 Main Residency Match","url":"https://www.nrmp.org/wp-content/uploads/2025/03/Advance_Data_Tables_2025.pdf"},
    {"title":"NRMP: 2025 Main Residency Match results announcement","url":"https://www.nrmp.org/about/news/2025/03/national-resident-matching-program-releases-the-2025-main-residency-match-results-celebrates-the-next-generation-of-physicians/"},
    {"title":"NRMP: 2027 Main Residency Match calendar","url":"https://www.nrmp.org/wp-content/uploads/2026/03/2027-Main-Residency-Match-Calendar-FINAL.pdf"},
    {"title":"NRMP: 2027 Main Residency Match applicant checklist","url":"https://www.nrmp.org/wp-content/uploads/2026/04/2027-MRM-Applicant-Checklist-FINAL.pdf"}
  ]'::jsonb,
  'https://www.nrmp.org/wp-content/uploads/2025/03/Advance_Data_Tables_2025.pdf',
  'Sources and further reading',
  true,
  '2026-09-04 12:00:00+00'::timestamptz
)
on conflict (slug) do update set
  title = excluded.title,
  excerpt = excluded.excerpt,
  content = excluded.content,
  paragraph_1 = excluded.paragraph_1,
  paragraph_2 = excluded.paragraph_2,
  paragraph_3 = excluded.paragraph_3,
  paragraph_4 = excluded.paragraph_4,
  category = excluded.category,
  author_name = excluded.author_name,
  image_urls = excluded.image_urls,
  image_alt_texts = excluded.image_alt_texts,
  image_url_1 = excluded.image_url_1,
  image_url_2 = excluded.image_url_2,
  source_links = excluded.source_links,
  relevant_link = excluded.relevant_link,
  link_title = excluded.link_title,
  published = excluded.published,
  published_at = excluded.published_at,
  updated_at = now();

do $$
declare
  published_count integer;
begin
  select count(*)
  into published_count
  from public.blog_posts
  where slug = '2025-match-statistics-lessons-for-2027-applicants'
    and category = 'Residency Interviews'
    and author_name = 'Magna-Q Editorial Team'
    and published
    and published_at::date = '2026-09-04'::date
    and jsonb_array_length(source_links) = 4
    and cardinality(image_urls) = 2;

  if published_count <> 1 then
    raise exception 'Expected one published, sourced 2025 Match statistics article; found %', published_count;
  end if;
end;
$$;

commit;
